package br.com.omnilog.view;
import br.com.omnilog.controller.CustomerController;import javafx.application.Application;import javafx.collections.FXCollections;import javafx.scene.Scene;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public final class OmniLogDesktop extends Application {public void start(Stage stage){Label title=new Label("OMNILOG HUB — Desktop Operations");title.setStyle("-fx-font-size:20px;-fx-font-weight:bold;");TextField search=new TextField();search.setPromptText("Search customer name or e-mail");Button find=new Button("Search");TableView<br.com.omnilog.model.Customer> table=new TableView<>();var name=new TableColumn<br.com.omnilog.model.Customer,String>("Name");name.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().name()));var email=new TableColumn<br.com.omnilog.model.Customer,String>("E-mail");email.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().email()));table.getColumns().addAll(name,email);Label status=new Label("Ready");find.setOnAction(e->{try{table.setItems(FXCollections.observableArrayList(new CustomerController().pesquisar(search.getText())));status.setText("Records: "+table.getItems().size());}catch(Exception ex){status.setText("Database error. Check DB settings and connection.");}});search.setOnAction(e->find.fire());MenuBar menu=new MenuBar(new Menu("File"),new Menu("Customers"),new Menu("Help"));VBox root=new VBox(menu,title,new HBox(8,search,find),table,status);root.setSpacing(12);root.setStyle("-fx-padding:20;-fx-background-color:white;");stage.setTitle("OMNILOG HUB");stage.setScene(new Scene(root,900,600));stage.show();}public static void main(String[] args){launch(args);}}
